DEFAULTS = {name: spec[2] for name, spec in PARAMS.items()}


def clamp(name, value):
    """Clamp `value` into the declared range of Vital parameter `name`."""
    spec = PARAMS.get(name)
    if spec is None:
        return value
    return max(spec[0], min(spec[1], value))
